import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
        s = list(next(iterator))
    except StopIteration:
        return

    active = [True] * n

    for _ in range(m):
        try:
            l_str = next(iterator)
            r_str = next(iterator)
            c = next(iterator)
        except StopIteration:
            break

        l = int(l_str)
        r = int(r_str)

        count = 0
        i = 0
        while i < n and count < r:
            if active[i]:
                current_pos = count + 1
                if current_pos >= l:
                    if s[i] == c:
                        active[i] = False
                count += 1
            i += 1

    result = []
    for i in range(n):
        if active[i]:
            result.append(s[i])

    print(''.join(result))

if __name__ == '__main__':
    main()
